#include <stdio.h>

#define P 11
#define MAXN 64

typedef struct Node { int key; int next; } Node;

Node pool[MAXN];
int head[P];
int pcnt = 0;

int main(void) {
    int i, kk, h0, probes;
    int keys[] = {47, 7, 29, 11, 16, 92, 22, 8, 3};
    int k = (int)(sizeof(keys) / sizeof(keys[0]));
    int blen[P];
    int tot_probe = 0, maxlen = 0;
    double asl;
    for (i = 0; i < P; i++) { head[i] = -1; blen[i] = 0; }
    for (kk = 0; kk < k; kk++) {
        h0 = keys[kk] % P;
        probes = blen[h0] + 1;
        blen[h0]++;
        tot_probe += probes;
        pool[pcnt].key = keys[kk];
        pool[pcnt].next = head[h0];
        head[h0] = pcnt;
        pcnt++;
    }
    for (i = 0; i < P; i++) {
        int c = 0;
        int p = head[i];
        while (p != -1) { c++; p = pool[p].next; }
        if (c > maxlen) maxlen = c;
        if (c > 0) printf("桶 %2d: 链长=%d\n", i, c);
    }
    asl = (double)tot_probe / (double)k;
    printf("拉链法 桶数=%d 关键字数=%d 查找成功ASL=%.3f 最长链=%d\n", P, k, asl, maxlen);
    return 0;
}
